import { useCallback, useEffect, useRef, useState } from "react";
import { BuildControlBar } from "./BuildControlBar";
import { BuildRulers } from "./BuildRulers";
import {
  Agent,
  AGENT_ROSTER,
  BuildLayer,
  LayerType,
  Particle,
  RegistrationMark
} from "./buildAnimationTypes";

interface BuildAnimationProps {
  onBuildComplete?: () => void;
}

export default function BuildAnimation({ onBuildComplete }: BuildAnimationProps) {
  const [isBypassed, setIsBypassed] = useState(false);
  const [isComplete, setIsComplete] = useState(false);
  const [isTouring, setIsTouring] = useState(true);
  const [speed, setSpeed] = useState<number>(1);
  const [isPaused, setIsPaused] = useState(false);
  const [buildDuration, setBuildDuration] = useState(0);

  const [layersCount, setLayersCount] = useState({ total: 0, completed: 0 });
  const [activeAgents, setActiveAgents] = useState<Agent[]>([]);
  const [activeParticles, setActiveParticles] = useState<Particle[]>([]);
  const [scrollYState, setScrollYState] = useState(0);
  const [frontierYState, setFrontierYState] = useState(0);
  const [registrationMarks, setRegistrationMarks] = useState<RegistrationMark[]>([]);

  // Refs for high-speed simulation loop
  const layersRef = useRef<BuildLayer[]>([]);
  const agentsRef = useRef<Agent[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const isTouringRef = useRef(true);
  const speedRef = useRef(1);
  const isPausedRef = useRef(false);
  const isCompleteRef = useRef(false);
  const buildStartTimeRef = useRef<number>(0);
  const lastTimeRef = useRef<number>(0);
  const reinforcementTimerRef = useRef<number>(0);
  const maxAgentsRef = useRef(24);
  const frontierYRef = useRef(0);
  const animFrameIdRef = useRef<number>(0);
  const totalLayersRef = useRef(0);
  const completedLayersRef = useRef(0);

  // Sync state refs
  isTouringRef.current = isTouring;
  speedRef.current = speed;
  isPausedRef.current = isPaused;

  // Check if reduced-motion or ?nobuild is present
  useEffect(() => {
    if (typeof window === "undefined") return;
    const isReduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const isNoBuild = window.location.search.includes("nobuild");

    if (isReduced || isNoBuild) {
      setIsBypassed(true);
      document.documentElement.classList.remove("build-pending");
      if (onBuildComplete) onBuildComplete();
    }
  }, [onBuildComplete]);

  // Clean all layer element inline styles
  const cleanAllLayers = useCallback(() => {
    layersRef.current.forEach((layer) => {
      if (layer.element) {
        layer.element.style.opacity = "";
        layer.element.style.clipPath = "";
        layer.element.style.filter = "";
        layer.element.style.transform = "";
        layer.element.style.visibility = "";
      }
    });
  }, []);

  // Initialize Layer Discovery and Agents
  const initBuild = useCallback(() => {
    if (typeof window === "undefined") return;

    // Remove any flash prevention class once we are ready to hide individual elements
    document.documentElement.classList.remove("build-pending");

    const isMobile = window.innerWidth < 768;
    maxAgentsRef.current = isMobile ? 8 : 26;
    const initialAgentCount = isMobile ? 6 : 12;

    // Discover elements inside #root
    const rootEl = document.getElementById("root") || document.body;
    const allCandidates = rootEl.querySelectorAll<HTMLElement>(
      'h1, h2, h3, h4, h5, h6, p, img, svg, video, canvas, a, button, li, [data-build="hero-letter"], [data-build="container"], [data-build="media"], [data-build="text"], [data-build="interactive"], .b'
    );

    const collectedLayers: BuildLayer[] = [];
    const collectedElements = new Set<HTMLElement>();

    // Pass 1: Identify all matching elements, skipping children of non-container elements
    allCandidates.forEach((el, index) => {
      // Ignore if element is inside an already-collected non-container element
      let parent = el.parentElement;
      let isInsideNonContainer = false;
      while (parent && parent !== rootEl) {
        if (
          collectedElements.has(parent) &&
          !parent.classList.contains("b") &&
          parent.getAttribute("data-build") !== "container"
        ) {
          isInsideNonContainer = true;
          break;
        }
        parent = parent.parentElement;
      }

      // Check if element has dimension
      const rect = el.getBoundingClientRect();
      if (rect.width === 0 || rect.height === 0 || isInsideNonContainer) {
        return;
      }

      collectedElements.add(el);

      const docTop = rect.top + window.scrollY;
      const docLeft = rect.left + window.scrollX;

      // Determine Layer Type
      let type: LayerType = "text";
      if (el.getAttribute("data-build") === "hero-letter") {
        type = "hero-letter";
      } else if (
        el.classList.contains("b") ||
        el.getAttribute("data-build") === "container" ||
        el.tagName === "SECTION"
      ) {
        type = "container";
      } else if (
        el.tagName === "IMG" ||
        el.tagName === "SVG" ||
        el.tagName === "VIDEO" ||
        el.tagName === "CANVAS" ||
        el.getAttribute("data-build") === "media"
      ) {
        type = "media";
      } else if (
        el.tagName === "A" ||
        el.tagName === "BUTTON" ||
        el.getAttribute("data-build") === "interactive"
      ) {
        type = "button";
      }

      // Generate a human-friendly tag label (e.g. h1.hero · 420 × 90)
      const tagName = el.tagName.toLowerCase();
      const firstClass = el.className && typeof el.className === "string" ? el.className.split(" ")[0] : "";
      const classStr = firstClass && !firstClass.includes(":") ? `.${firstClass.slice(0, 8)}` : "";
      const tagLabel = `${tagName}${classStr} · ${Math.round(rect.width)} × ${Math.round(rect.height)}`;

      // Set element initial hidden state
      el.style.opacity = "0";

      collectedLayers.push({
        id: `layer-${index}-${Math.random().toString(36).slice(2, 6)}`,
        element: el,
        rect: {
          top: rect.top,
          left: rect.left,
          width: rect.width,
          height: rect.height
        },
        docTop,
        docLeft,
        type,
        tagLabel,
        status: "pending",
        domIndex: index
      });
    });

    // Sort layers in ~60px bands top to bottom, DOM order within each band
    collectedLayers.sort((a, b) => {
      const bandA = Math.floor(a.docTop / 60);
      const bandB = Math.floor(b.docTop / 60);
      if (bandA !== bandB) return bandA - bandB;
      return a.domIndex - b.domIndex;
    });

    layersRef.current = collectedLayers;
    totalLayersRef.current = collectedLayers.length;
    completedLayersRef.current = 0;
    setLayersCount({ total: collectedLayers.length, completed: 0 });

    // Generate scattered registration marks across document height
    const docHeight = Math.max(document.body.scrollHeight, 2400);
    const marks: RegistrationMark[] = [];
    const stepX = 260;
    const stepY = 320;
    for (let y = 140; y < docHeight; y += stepY) {
      for (let x = 80; x < window.innerWidth - 60; x += stepX) {
        marks.push({
          id: `mark-${x}-${y}`,
          x: x + (Math.random() * 40 - 20),
          y: y + (Math.random() * 40 - 20)
        });
      }
    }
    setRegistrationMarks(marks);

    // Initial agent pool
    const agents: Agent[] = [];
    for (let i = 0; i < initialAgentCount; i++) {
      const roster = AGENT_ROSTER[i % AGENT_ROSTER.length];
      agents.push({
        id: `agent-${i}-${roster.name}`,
        name: roster.name,
        color: roster.color,
        x: -70 - Math.random() * 120,
        y: Math.random() * (window.innerHeight * 0.45) + 60,
        targetX: Math.random() * (window.innerWidth * 0.6) + 100,
        targetY: Math.random() * 200 + 100,
        state: "entering",
        taskProgress: 0,
        taskDuration: 0.4,
        restTimer: 0,
        driftAngle: Math.random() * Math.PI * 2,
        driftRadius: 18 + Math.random() * 22,
        driftSpeed: 1.2 + Math.random() * 0.8
      });
    }

    agentsRef.current = agents;
    setActiveAgents([...agents]);
    frontierYRef.current = 0;
    buildStartTimeRef.current = performance.now();
    lastTimeRef.current = performance.now();
    reinforcementTimerRef.current = 0;
    isCompleteRef.current = false;
    setIsComplete(false);
  }, []);

  // Skip Build: reveal all immediately
  const handleSkip = useCallback(() => {
    cleanAllLayers();
    layersRef.current.forEach((l) => (l.status = "done"));
    completedLayersRef.current = totalLayersRef.current;
    setLayersCount({ total: totalLayersRef.current, completed: totalLayersRef.current });
    isCompleteRef.current = true;
    setIsComplete(true);
    setBuildDuration((performance.now() - buildStartTimeRef.current) / 1000);
    if (onBuildComplete) onBuildComplete();
  }, [cleanAllLayers, onBuildComplete]);

  // Replay Build: restart from beginning
  const handleReplay = useCallback(() => {
    window.scrollTo({ top: 0, behavior: "smooth" });
    setIsTouring(true);
    initBuild();
  }, [initBuild]);

  // Main Animation Loop
  useEffect(() => {
    if (isBypassed) return;

    initBuild();

    const handleWheelOrTouch = () => {
      if (isTouringRef.current) {
        isTouringRef.current = false;
        setIsTouring(false);
      }
    };

    window.addEventListener("wheel", handleWheelOrTouch, { passive: true });
    window.addEventListener("touchstart", handleWheelOrTouch, { passive: true });
    window.addEventListener("keydown", (e) => {
      if (["ArrowUp", "ArrowDown", "PageUp", "PageDown", " "].includes(e.key)) {
        handleWheelOrTouch();
      }
    });

    let frameCount = 0;

    const loop = (now: number) => {
      const rawDelta = Math.min(0.08, (now - lastTimeRef.current) / 1000);
      lastTimeRef.current = now;

      // Simulated clock delta
      const dt = isPausedRef.current ? 0 : rawDelta * speedRef.current;

      frameCount++;

      const agents = agentsRef.current;
      const layers = layersRef.current;

      if (!isCompleteRef.current && dt > 0) {
        // Reinforcements: add new agents every ~2.2s up to maxAgents
        reinforcementTimerRef.current += dt;
        if (
          reinforcementTimerRef.current >= 2.2 &&
          agents.length < maxAgentsRef.current &&
          completedLayersRef.current < totalLayersRef.current - 4
        ) {
          reinforcementTimerRef.current = 0;
          const nextIdx = agents.length;
          const roster = AGENT_ROSTER[nextIdx % AGENT_ROSTER.length];
          agents.push({
            id: `agent-${nextIdx}-${roster.name}`,
            name: roster.name,
            color: roster.color,
            x: -80,
            y: Math.random() * (window.innerHeight * 0.45) + window.scrollY + 60,
            targetX: Math.random() * (window.innerWidth * 0.6) + 100,
            targetY: frontierYRef.current + Math.random() * 150,
            state: "entering",
            taskProgress: 0,
            taskDuration: 0.4,
            restTimer: 0,
            driftAngle: Math.random() * Math.PI * 2,
            driftRadius: 20,
            driftSpeed: 1.5
          });
        }

        // Find current build frontier: highest active/done layer docTop
        let maxActiveTop = frontierYRef.current;
        layers.forEach((l) => {
          if (l.status === "building" || l.status === "done") {
            if (l.docTop > maxActiveTop) {
              maxActiveTop = l.docTop;
            }
          }
        });
        frontierYRef.current = maxActiveTop;

        // Auto-touring: smoothly scroll so frontier sits ~32% down the viewport
        if (isTouringRef.current) {
          const targetScroll = Math.max(0, frontierYRef.current - window.innerHeight * 0.32);
          const currentScroll = window.scrollY;
          if (Math.abs(targetScroll - currentScroll) > 1.5) {
            window.scrollTo(0, currentScroll + (targetScroll - currentScroll) * 0.08 * speedRef.current);
          }
        }

        // Job Assignment: match nearest idle agent to candidate layers near frontier
        const availableLayers = layers.filter(
          (l) => l.status === "pending" && l.docTop <= frontierYRef.current + 320
        );

        const idleAgents = agents.filter(
          (a) => a.state === "idle" || a.state === "entering"
        );

        if (availableLayers.length > 0 && idleAgents.length > 0) {
          availableLayers.forEach((layer) => {
            if (layer.status !== "pending") return;

            // Find closest idle agent
            let nearestAgent: Agent | null = null;
            let minDist = Infinity;

            idleAgents.forEach((agent) => {
              if (agent.state === "idle" || agent.state === "entering") {
                const dist = Math.hypot(agent.x - layer.docLeft, agent.y - layer.docTop);
                if (dist < minDist) {
                  minDist = dist;
                  nearestAgent = agent;
                }
              }
            });

            if (nearestAgent) {
              const a = nearestAgent as Agent;
              layer.status = "building";
              layer.assignedAgentId = a.id;
              a.currentLayerId = layer.id;
              a.state = "flying";
              a.targetX = layer.docLeft;
              a.targetY = layer.docTop;
              a.taskProgress = 0;

              // Task duration based on layer type
              if (layer.type === "hero-letter") {
                a.taskDuration = 0.28;
              } else if (layer.type === "media") {
                a.taskDuration = 0.55;
              } else if (layer.type === "container") {
                a.taskDuration = 0.48;
              } else {
                a.taskDuration = 0.38;
              }
            }
          });
        }

        // Update Agents
        agents.forEach((agent) => {
          // 1. Entering / Idle Drift
          if (agent.state === "entering" || agent.state === "idle") {
            agent.driftAngle += agent.driftSpeed * dt;
            const driftBaseX = window.innerWidth * 0.5;
            const driftBaseY = frontierYRef.current + 120;
            const targetX = driftBaseX + Math.cos(agent.driftAngle) * (window.innerWidth * 0.35);
            const targetY = driftBaseY + Math.sin(agent.driftAngle) * agent.driftRadius;

            agent.x += (targetX - agent.x) * (0.08 * (1 + dt));
            agent.y += (targetY - agent.y) * (0.08 * (1 + dt));
            agent.state = "idle";
          }

          // 2. Flying to assigned layer
          else if (agent.state === "flying") {
            const dx = agent.targetX - agent.x;
            const dy = agent.targetY - agent.y;
            const dist = Math.hypot(dx, dy);

            if (dist < 12) {
              agent.state = "building";
              agent.taskProgress = 0;
            } else {
              agent.x += dx * Math.min(1, dt * 7.5);
              agent.y += dy * Math.min(1, dt * 7.5);
            }
          }

          // 3. Building layer with type-specific effects
          else if (agent.state === "building") {
            const layer = layers.find((l) => l.id === agent.currentLayerId);
            if (!layer) {
              agent.state = "idle";
              return;
            }

            agent.taskProgress += dt / agent.taskDuration;
            const progress = Math.min(1, agent.taskProgress);
            const el = layer.element;

            // Type 1: Text - clip-path wipe left->right, cursor tracks typing caret
            if (layer.type === "text" || layer.type === "button") {
              el.style.opacity = "1";
              el.style.clipPath = `inset(0 ${(1 - progress) * 100}% 0 0)`;
              agent.x = layer.docLeft + layer.rect.width * progress;
              agent.y = layer.docTop + layer.rect.height * 0.65;
            }
            // Type 2: Media - scan top->bottom from bright blur/grayscale to crisp color
            else if (layer.type === "media") {
              el.style.opacity = "1";
              const gray = (1 - progress) * 100;
              const blur = (1 - progress) * 8;
              const brightness = 1 + (1 - progress) * 0.4;
              el.style.filter = `grayscale(${gray}%) blur(${blur}px) brightness(${brightness})`;
              agent.x = layer.docLeft + layer.rect.width * 0.5;
              agent.y = layer.docTop + layer.rect.height * progress;
            }
            // Type 3: Container - grows from top-left as cursor drags bottom-right corner
            else if (layer.type === "container") {
              el.style.opacity = "1";
              el.style.transformOrigin = "top left";
              const scale = 0.2 + 0.8 * progress;
              el.style.transform = `scale(${scale})`;
              agent.x = layer.docLeft + layer.rect.width * progress;
              agent.y = layer.docTop + layer.rect.height * progress;
            }
            // Type 4: Giant Hero Letter - rises from blur one by one
            else if (layer.type === "hero-letter") {
              el.style.opacity = String(progress);
              const blur = (1 - progress) * 12;
              const translateY = (1 - progress) * 16;
              el.style.filter = `blur(${blur}px)`;
              el.style.transform = `translateY(${translateY}px)`;
              agent.x = layer.docLeft + layer.rect.width * 0.5;
              agent.y = layer.docTop + layer.rect.height * 0.8;
            }

            // Task completion
            if (progress >= 1) {
              el.style.opacity = "1";
              el.style.clipPath = "";
              el.style.filter = "";
              el.style.transform = "";

              layer.status = "done";
              completedLayersRef.current += 1;

              agent.state = "resting";
              agent.restTimer = 0.08;
            }
          }

          // 4. Resting briefly before taking next job
          else if (agent.state === "resting") {
            agent.restTimer -= dt;
            if (agent.restTimer <= 0) {
              agent.state = "idle";
              agent.currentLayerId = undefined;
            }
          }
        });

        // Check if all layers are complete
        if (completedLayersRef.current >= totalLayersRef.current && totalLayersRef.current > 0) {
          isCompleteRef.current = true;
          setIsComplete(true);
          const duration = (performance.now() - buildStartTimeRef.current) / 1000;
          setBuildDuration(duration);

          // Launch celebratory finale: agents fly off to top-right with glowing particle sparks!
          agents.forEach((agent) => {
            agent.state = "flying-away";
            agent.targetX = window.innerWidth + 280 + Math.random() * 200;
            agent.targetY = window.scrollY - 300 - Math.random() * 200;
          });

          if (onBuildComplete) onBuildComplete();
        }
      }

      // Finale: Agents fly away to top-right + emit glowing particle trails
      if (isCompleteRef.current && dt > 0) {
        const particles = particlesRef.current;

        agents.forEach((agent) => {
          if (agent.state === "flying-away") {
            agent.x += (agent.targetX - agent.x) * Math.min(1, dt * 4.5);
            agent.y += (agent.targetY - agent.y) * Math.min(1, dt * 4.5);

            // Spawn particle trails
            if (Math.random() < 0.6) {
              particles.push({
                id: Math.random(),
                x: agent.x,
                y: agent.y,
                vx: (Math.random() - 0.5) * 60,
                vy: (Math.random() - 0.5) * 60,
                color: agent.color,
                size: 3 + Math.random() * 3,
                alpha: 1,
                life: 0,
                maxLife: 0.6 + Math.random() * 0.4
              });
            }
          }
        });

        // Update particles
        for (let i = particles.length - 1; i >= 0; i--) {
          const p = particles[i];
          p.life += dt;
          p.x += p.vx * dt;
          p.y += p.vy * dt;
          p.alpha = 1 - p.life / p.maxLife;

          if (p.life >= p.maxLife) {
            particles.splice(i, 1);
          }
        }
      }

      // Sync React state for UI renders every 2-3 animation frames for peak 60fps
      if (frameCount % 2 === 0) {
        setActiveAgents([...agents]);
        setActiveParticles([...particlesRef.current]);
        setLayersCount({
          total: totalLayersRef.current,
          completed: completedLayersRef.current
        });
        setScrollYState(window.scrollY);
        setFrontierYState(frontierYRef.current);
      }

      animFrameIdRef.current = requestAnimationFrame(loop);
    };

    animFrameIdRef.current = requestAnimationFrame(loop);

    return () => {
      cancelAnimationFrame(animFrameIdRef.current);
      window.removeEventListener("wheel", handleWheelOrTouch);
      window.removeEventListener("touchstart", handleWheelOrTouch);
    };
  }, [initBuild, isBypassed, onBuildComplete]);

  if (isBypassed) {
    return null;
  }

  // Active selection boxes currently being built
  const activeBuildingLayers = layersRef.current.filter((l) => l.status === "building");

  return (
    <>
      {/* Design-Tool Pixel Rulers & Registration Marks */}
      <BuildRulers
        scrollY={scrollYState}
        frontierY={frontierYState}
        isComplete={isComplete}
        registrationMarks={registrationMarks}
      />

      {/* Main Agent Overlay in Document Coordinates */}
      <div
        className="pointer-events-none absolute inset-0 overflow-visible z-[9990]"
        style={{
          width: "100%",
          height: `${Math.max(document.body.scrollHeight, 2400)}px`
        }}>
        {/* 1. Selection Boxes around active elements */}
        {activeBuildingLayers.map((layer) => {
          const agent = activeAgents.find((a) => a.id === layer.assignedAgentId);
          if (!agent) return null;

          return (
            <div
              key={`box-${layer.id}`}
              style={{
                position: "absolute",
                left: `${layer.docLeft}px`,
                top: `${layer.docTop}px`,
                width: `${layer.rect.width}px`,
                height: `${layer.rect.height}px`,
                borderColor: agent.color,
                backgroundColor: `${agent.color}15`
              }}
              className="border border-solid transition-opacity duration-150 select-none">
              {/* Corner anchor handles */}
              <span
                className="absolute -top-1 -left-1 w-2 h-2 border border-white"
                style={{ backgroundColor: agent.color }}
              />
              <span
                className="absolute -top-1 -right-1 w-2 h-2 border border-white"
                style={{ backgroundColor: agent.color }}
              />
              <span
                className="absolute -bottom-1 -left-1 w-2 h-2 border border-white"
                style={{ backgroundColor: agent.color }}
              />
              <span
                className="absolute -bottom-1 -right-1 w-2 h-2 border border-white"
                style={{ backgroundColor: agent.color }}
              />

              {/* Micro tag label badge */}
              <div
                className="absolute -top-5 left-0 flex items-center gap-1 px-1.5 py-0.5 rounded-xs font-mono text-[9px] font-bold text-white shadow-sm whitespace-nowrap"
                style={{ backgroundColor: agent.color }}>
                <span>{layer.tagLabel}</span>
              </div>

              {/* Bottom progress bar */}
              <div className="absolute bottom-0 left-0 h-[2px] w-full bg-white/20 overflow-hidden">
                <div
                  className="h-full transition-all duration-75"
                  style={{
                    width: `${Math.min(100, Math.max(0, agent.taskProgress * 100))}%`,
                    backgroundColor: agent.color
                  }}
                />
              </div>
            </div>
          );
        })}

        {/* 2. Particle Trails during celebratory finale */}
        {activeParticles.map((p) => (
          <div
            key={p.id}
            style={{
              position: "absolute",
              left: `${p.x}px`,
              top: `${p.y}px`,
              width: `${p.size}px`,
              height: `${p.size}px`,
              backgroundColor: p.color,
              opacity: p.alpha,
              borderRadius: "50%",
              boxShadow: `0 0 6px ${p.color}`,
              transform: "translate(-50%, -50%)"
            }}
          />
        ))}

        {/* 3. Colorful Arrow Cursors with Name Tags */}
        {activeAgents.map((agent) => (
          <div
            key={agent.id}
            style={{
              position: "absolute",
              left: `${agent.x}px`,
              top: `${agent.y}px`,
              transform: "translate3d(0, 0, 0)",
              zIndex: 9992
            }}
            className="flex items-start select-none transition-transform duration-75">
            {/* SVG Cursor Pointer with white outline & drop shadow */}
            <svg
              width="22"
              height="22"
              viewBox="0 0 24 24"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
              style={{ filter: "drop-shadow(0px 2px 4px rgba(0,0,0,0.5))" }}>
              <path
                d="M3 3L10.07 20.97L13.58 13.58L20.97 10.07L3 3Z"
                fill={agent.color}
                stroke="#ffffff"
                strokeWidth="1.8"
                strokeLinejoin="round"
              />
            </svg>

            {/* Name Tag Pill */}
            <div
              className="ml-1 -mt-0.5 flex items-center gap-1 rounded-sm px-1.5 py-0.5 text-[10px] font-mono font-bold uppercase tracking-wider text-white shadow-md"
              style={{
                backgroundColor: agent.color,
                filter: "drop-shadow(0px 2px 5px rgba(0,0,0,0.4))"
              }}>
              <span>{agent.name}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Floating Glassy Control Bar */}
      <BuildControlBar
        agents={activeAgents}
        totalLayers={layersCount.total}
        completedLayers={layersCount.completed}
        isTouring={isTouring}
        onToggleTouring={() => setIsTouring((prev) => !prev)}
        speed={speed}
        onChangeSpeed={() => setSpeed((prev) => (prev === 1 ? 2 : prev === 2 ? 4 : 1))}
        isPaused={isPaused}
        onTogglePause={() => setIsPaused((prev) => !prev)}
        onSkip={handleSkip}
        isComplete={isComplete}
        buildDuration={buildDuration}
        onReplay={handleReplay}
      />
    </>
  );
}
